def scope_section(num):
    services = tbl(['القسم', 'نموذج التشغيل', 'كيف يطلب العميل', 'المتطلبات'], [
        ['<b>مطاعم</b>', 'منيو بفترات وتوفر منتجات', 'سلة فرع واحد ودفع واحد؛ الاستلام الذاتي متاح', refs_html(['MER-046', 'MER-005', 'ORD-003'])],
        ['<b>مارت</b>', 'بقالات مستقلة بكتالوج (أساسي أو ثانوي أو عام)', 'يختار البقالة ثم منتجاتها؛ بلا استلام ذاتي', refs_html(['DSP-005', 'MER-010', 'CAT-001'])],
        ['<b>شوبز</b>', 'منيو أو كتابة، ويحوّل موظف المنصة بينهما', 'سلة منيو، أو نموذج كتابة بدفعتين', refs_html(['MER-046', 'MER-053', 'ORD-013'])],
        ['<b>صيدليات</b>', 'كتابة بمراجعة الصيدلي', 'كتابة الطلب مع الوصفة، دفعة توصيل ثم فاتورة المنتجات', refs_html(['PHR-012', 'ORD-013', 'EXT-004'])],
        ['<b>استلم بنفسك</b>', 'خدمة مرتبطة بالفرع لطلبات المنيو في غير المارت', 'يدفع العميل، وبعد 60 ثانية يصل الطلب للتاجر، ثم يستلمه العميل من الفرع', refs_html(['EXT-006'])],
        ['<b>Taxi</b>', '<span class="tag p4">بنية مؤجلة</span>', 'غير متاح في الإطلاق', refs_html(['TAX-FND'])],
    ])
    mods = collections.OrderedDict()
    for r in D['requirements']:
        m = r['id'].split('-')[0]
        mods.setdefault(m, collections.Counter())[r['priority']] += 1
    rows = []
    for m, name in MODULES:
        if m not in mods:
            continue
        c = mods[m]
        rows.append([esc(name) + ' <bdi class="rid">%s</bdi>' % m, str(c['launch'] or '—'), str(c['important'] or '—'), str(c['later'] or '—'), str(c['foundation'] or '—'), str(sum(c.values()))])
    rows.append(['<b>المجموع</b>', '<b>%d</b>' % COUNT['launch'], '<b>%d</b>' % COUNT['important'], '<b>%d</b>' % COUNT['later'], '<b>%d</b>' % COUNT['foundation'], '<b>%d</b>' % N_REQ])
    counts = tbl(['الوحدة', 'أساسي', 'مهم', 'لاحقاً', 'بنية', 'المجموع'], rows)

    def listing(pri, label):
        by = collections.OrderedDict()
        for m, _ in MODULES:
            items = [r for r in D['requirements'] if r['priority'] == pri and r['id'].startswith(m + '-')]
            if items:
                by[m] = items
        return '<details class="req-list"><summary>%s <span class="cnt">%d</span></summary>%s</details>' % (label, COUNT[pri], ''.join(
            '<h4>%s</h4><ul class="reqlist">%s</ul>' % (esc(MOD_NAME[m]), ''.join('<li>%s</li>' % req_link(r['id']) for r in items)) for m, items in by.items()))
    excl = tbl(['ما استُبعد', 'الحكم المعتمد', 'المتطلبات'], [['<b>%s</b>' % esc(a), esc(b), refs_html(c)] for a, b, c in EXCLUDED])
    return sec('scope', num, 'نطاق الإصدار الأول', 'ما يُبنى الآن، وما يؤجَّل، وما استُبعد بقرار صريح.',
               '<h3>الخدمات</h3>' + services + '<h3>ما استُبعد من الإطلاق</h3>' + excl +
               '<h3>المتطلبات بحسب الوحدة والأولوية</h3>' + counts +
               '<h3>قوائم المؤجَّل والمهم</h3><p>«أساسي للإطلاق» هو الباقي، ويراه المبرمج في فهرس المتطلبات بالتصفية.</p>' +
               listing('later', 'لاحقاً') + listing('important', 'مهم (بعد الأساس مباشرة)') + listing('foundation', 'بنية مؤجلة'))


