def prelaunch_section(num):
    cards = ''.join('<article><span class="rid">%s</span><h4>%s</h4><p>%s</p></article>' % (esc(i), esc(t), fmt(b)) for i, t, b in D['open'])
    rows = [['<b>%s</b>' % a, fmt(b), refs_html(c)] for a, b, c in PREREQ]
    return sec('prelaunch', num, 'قبل التشغيل', 'بيانات وقيم تُجهَّز قبل الإطلاق، وهي إعدادات تشغيل لا تغيّر قرارات المنتج.',
               '<div class="open-items">%s</div><h3>ما تشترطه المتطلبات نفسها</h3>%s' % (cards, tbl(['متى', 'الشرط', 'المتطلب'], rows)))


